def normalize(value):
    if isinstance(value, bool):
        raise ValueError("booléen non autorisé")
    if isinstance(value, str):
        raise ValueError("chaîne non autorisée")
    if isinstance(value, float):
        raise ValueError("flottant non autorisé")
    if not isinstance(value, int):
        raise ValueError("type non supporté")
    if 1 <= value <= 65535:
        return value
    return 8091
